package com.talent.hr.repository;

import com.talent.hr.entity.PerformanceReview;
import org.springframework.data.repository.PagingAndSortingRepository;
import org.springframework.data.rest.core.annotation.RepositoryRestResource;
import org.springframework.security.access.prepost.PostAuthorize;
import java.util.Optional;

@RepositoryRestResource(path = "appraisal-reviews")
public interface PerformanceReviewRepository extends PagingAndSortingRepository<PerformanceReview, Long> {

    @PostAuthorize("returnObject.isPresent() and (returnObject.get().employeeId == principal.id or returnObject.get().reviewerId == principal.id or hasRole('HR_ADMIN'))")
    Optional<PerformanceReview> findById(Long id);
}
